import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_settings() -> dict[str, Any]:
    out: dict[str, Any] = {
        "confirmation_mode": "shadow",
        "time_zone": "Australia/Sydney",
        "cutoff_time": "",
        "delivery_days": "every_day",
        "missing_po": "customer_rule",
        "guessed_products": "always_ask",
        "unusual_quantity_factor": 5,
        "duplicate_window_days": 30,
        "substitutions": "never",
        "missing_unit": "ask",
    }
    try:
        saved = dict(api.extension.settings() or {})
    except Exception:
        saved = {}
    for key, value in saved.items():
        if value is not None and value != "":
            out[key] = value
    return out


import difflib

order_id = params["order_id"]
sender_email = od_text(params.get("sender_email")).lower()
customer_name = od_text(params.get("customer_name"))
hint = od_text(params.get("account_code")).upper()
# Every other organisation or site name the order mentions (who it is addressed to, the delivery site, a mess or
# branch name), so a shared sender such as a buying office does not hide the real customer.
seen_names = [n for n in [customer_name] + [od_text(n) for n in re.split(r"[;\n|]+", od_text(params.get("other_names_seen")))] if n]
domain = sender_email.split("@")[-1] if "@" in sender_email else ""
profiles = od_rows("od_customer_profiles")
chosen: dict[str, Any] = {}
match_how = "none"
confidence = "low"
by_code = {od_text(od_data(r).get("account_code")).upper(): r for r in profiles if od_text(od_data(r).get("account_code"))}
if hint and hint in by_code:
    chosen = by_code[hint]
    match_how = "account_code"
if not chosen:
    # An account code written anywhere in the names the order gave ("OR - DEF28717").
    tokens = set(re.findall(r"[A-Z0-9][A-Z0-9-]{3,}", " ".join(seen_names + [hint]).upper()))
    coded = [by_code[t] for t in tokens if t in by_code]
    if len({od_text(r.get("id")) for r in coded}) == 1:
        chosen = coded[0]
        match_how = "account_code"
domain_hits = [r for r in profiles if domain and od_text(od_data(r).get("email_domain")).lower() == domain]
if not chosen and len(domain_hits) == 1:
    chosen = domain_hits[0]
    match_how = "email_domain"
scored: list[tuple[float, dict[str, Any]]] = []
if not chosen and seen_names:
    # When several customers share the sender's address, only they are candidates.
    pool = domain_hits if len(domain_hits) > 1 else profiles
    for row in pool:
        best = 0.0
        names = [od_text(row.get("title"))] + re.split(r"[;,\n]+", od_text(od_data(row).get("other_names")))
        for name in names:
            known = od_norm(name)
            if not known:
                continue
            for seen in seen_names:
                wanted = od_norm(seen)
                if not wanted:
                    continue
                if known == wanted:
                    score = 1.0
                elif len(known) >= 5 and len(wanted) >= 5 and (known in wanted or wanted in known):
                    score = 0.95
                else:
                    score = difflib.SequenceMatcher(None, known, wanted).ratio()
                best = max(best, score)
        scored.append((best, row))
    scored.sort(key=lambda pair: -pair[0])
    if scored and scored[0][0] >= 0.86:
        top = scored[0][0]
        runner_up = scored[1][0] if len(scored) > 1 else 0.0
        # Two customers that fit equally well are not a match: a person or the reader picks.
        if top - runner_up >= 0.03 or (top == 1.0 and runner_up < 1.0):
            chosen = scored[0][1]
            match_how = "name" if top >= 0.95 else "name_guess"
        else:
            match_how = "ambiguous"
customer_found = bool(chosen)
if match_how in ("account_code", "email_domain", "name"):
    confidence = "high"
elif match_how == "name_guess":
    confidence = "medium"
candidates: list[dict[str, Any]] = []
if not customer_found:
    shortlist = [row for score, row in scored[:5] if score >= 0.5] or (domain_hits[:5] if len(domain_hits) > 1 else [])
    for row in shortlist:
        candidates.append({"account_code": od_text(od_data(row).get("account_code")), "name": od_text(row.get("title")), "other_names": od_text(od_data(row).get("other_names"))[:200]})
profile = od_data(chosen)
account_code = od_text(profile.get("account_code"))
known_name = od_text(chosen.get("title")) if chosen else ""
order_notes = od_text(profile.get("order_notes"))
order_rules = od_text(profile.get("order_rules"))
cutoff_time = od_text(profile.get("cutoff_time"))
po_required = bool(profile.get("po_required"))
auto_confirm = od_text(profile.get("auto_confirm")) or "follow_default"
addresses: list[dict[str, Any]] = []
if customer_found:
    for row in od_rows("od_delivery_addresses", account_code):
        d = od_data(row)
        if od_text(d.get("account_code")) != account_code:
            continue
        addresses.append({
            "address_id": od_text(row.get("id")),
            "label": od_text(row.get("title")),
            "address": od_text(d.get("address")),
            "site_code": od_text(d.get("site_code")),
            "delivery_days": list(d.get("delivery_days") or []),
            "is_default": bool(d.get("is_default")),
        })
# The name kept on the order is the customer's own when one was found, never the sender's.
update: dict[str, Any] = {"data": {"customer_name_raw": (known_name or customer_name)[:300], "account_code": account_code}}
client_ids = od_link_ids(chosen, "client")
if client_ids:
    update["links"] = {"client": client_ids[:1]}
api.records.update(type_slug="od_orders", record_id=order_id, record=update)
current = api.records.get(type_slug="od_orders", record_id=order_id) or {}
if od_text((current.get("record") or {}).get("stage")) == "received":
    api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="reading")
settings = od_settings()
house_rules = "Substitutions: only when this customer's notes or rules allow it. Always say what was swapped for what." if od_text(settings.get("substitutions")) == "customer_rules" else "Substitutions: never swap one product for another, even when the customer's notes allow it. Mark the line for review instead."
if not cutoff_time:
    cutoff_time = od_text(settings.get("cutoff_time"))
